How many times does the loop below allocate successfully before `alloc` fails?

```zig
var buffer: [20]u8 = undefined;
var fba: std.heap.FixedBufferAllocator = .init(&buffer);
const a = fba.allocator();
var ok: u32 = 0;
while (true) {
    _ = a.alloc(u8, 6) catch break;
    ok += 1;
}
std.debug.print("{d}\n", .{ok});
```

What does this program print?

```zig
const std = @import("std");

pub fn main(init: std.process.Init) !void {
    var counts: std.StringHashMap(u32) = .init(init.gpa);
    defer counts.deinit();
    var it = std.mem.tokenizeScalar(u8, "a b a c b a", ' ');
    while (it.next()) |w| {
        const slot = try counts.getOrPut(w);
        if (!slot.found_existing) slot.value_ptr.* = 0;
        slot.value_ptr.* += 1;
    }
    std.debug.print("{d} {d}\n", .{ counts.count(), counts.get("a").? });
}
```
